-- RpaAgentSystem initial schema (PostgreSQL 17). Development bootstrap migration.
-- Execute once on an empty database. Production migration strategy: EF Core migrations.
BEGIN;
CREATE TABLE IF NOT EXISTS "Tenants" ("Id" uuid PRIMARY KEY, "Name" text NOT NULL);
CREATE TABLE IF NOT EXISTS "Companies" ("Id" uuid PRIMARY KEY, "Name" text NOT NULL, "CreditCode" text NOT NULL UNIQUE, "RegionCode" text NOT NULL);
CREATE TABLE IF NOT EXISTS "GovernmentSystems" ("Id" uuid PRIMARY KEY, "Code" text NOT NULL UNIQUE, "Name" text NOT NULL, "RegionCode" text NOT NULL, "BusinessDomain" text NOT NULL);
CREATE TABLE IF NOT EXISTS "SystemOperations" ("Id" uuid PRIMARY KEY, "GovernmentSystemId" uuid NOT NULL REFERENCES "GovernmentSystems"("Id"), "OperationCode" text NOT NULL, "WorkflowCode" text NOT NULL, UNIQUE ("GovernmentSystemId","OperationCode"));
CREATE TABLE IF NOT EXISTS "TenantCompanies" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "CompanyId" uuid NOT NULL REFERENCES "Companies"("Id"), "Enabled" boolean NOT NULL DEFAULT true, "CreatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("TenantId","CompanyId"));
CREATE TABLE IF NOT EXISTS "BusinessAuthorizations" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "CompanyId" uuid NOT NULL REFERENCES "Companies"("Id"), "OperationCode" text NOT NULL, "ExpiresAt" timestamptz NULL, "CreatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "SystemAccounts" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "CompanyId" uuid NOT NULL REFERENCES "Companies"("Id"), "GovernmentSystemId" uuid NOT NULL REFERENCES "GovernmentSystems"("Id"), "AccountLabel" text NOT NULL, "CredentialReference" text NOT NULL, "AuthMethod" text NOT NULL, "Enabled" boolean NOT NULL DEFAULT true, "CreatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "BusinessRequests" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "CompanyId" uuid NOT NULL REFERENCES "Companies"("Id"), "OperationCode" text NOT NULL, "IdempotencyKey" text NOT NULL, "Status" text NOT NULL DEFAULT 'Pending', "SubmittedAt" timestamptz NULL, "CreatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("TenantId","IdempotencyKey"));
CREATE TABLE IF NOT EXISTS "BusinessRecords" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "BusinessRequestId" uuid NOT NULL REFERENCES "BusinessRequests"("Id"), "SubjectKey" text NOT NULL, "Status" text NOT NULL DEFAULT 'Pending', "ReceiptReference" text NULL, "CreatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("TenantId","BusinessRequestId","SubjectKey"));
CREATE TABLE IF NOT EXISTS "WorkflowDefinitions" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "Code" text NOT NULL, "Version" integer NOT NULL, "JsonDsl" text NOT NULL, "Published" boolean NOT NULL DEFAULT false, "CreatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("TenantId","Code","Version"));
CREATE TABLE IF NOT EXISTS "Workers" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "Name" text NOT NULL, "Platform" text NOT NULL, "CapabilitiesJson" text NOT NULL DEFAULT '[]', "LastHeartbeatAt" timestamptz NULL, "CreatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "WorkflowExecutions" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "BusinessRequestId" uuid NOT NULL REFERENCES "BusinessRequests"("Id"), "WorkflowDefinitionId" uuid NOT NULL REFERENCES "WorkflowDefinitions"("Id"), "Status" text NOT NULL DEFAULT 'Queued', "WorkerId" uuid NULL REFERENCES "Workers"("Id"), "CreatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "UsbDevices" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "DeviceKey" text NOT NULL, "CompanyId" uuid NULL REFERENCES "Companies"("Id"), "Status" text NOT NULL DEFAULT 'Offline', "CreatedAt" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "DeviceLeases" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "UsbDeviceId" uuid NOT NULL REFERENCES "UsbDevices"("Id"), "WorkerId" uuid NOT NULL REFERENCES "Workers"("Id"), "FencingToken" bigint NOT NULL, "ExpiresAt" timestamptz NOT NULL, "Status" text NOT NULL DEFAULT 'Active', "CreatedAt" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "IX_DeviceLeases_OneActive" ON "DeviceLeases" ("UsbDeviceId") WHERE "Status" = 'Active';
CREATE TABLE IF NOT EXISTS "ExecutionEvents" ("Id" uuid PRIMARY KEY, "TenantId" uuid NOT NULL REFERENCES "Tenants"("Id"), "WorkflowExecutionId" uuid NOT NULL REFERENCES "WorkflowExecutions"("Id"), "Sequence" bigint NOT NULL, "EventType" text NOT NULL, "RedactedPayload" text NOT NULL DEFAULT '{}', "CreatedAt" timestamptz NOT NULL DEFAULT now(), UNIQUE ("TenantId","WorkflowExecutionId","Sequence"));
CREATE INDEX IF NOT EXISTS "IX_SystemAccounts_TenantCompanySystem" ON "SystemAccounts" ("TenantId","CompanyId","GovernmentSystemId");
CREATE INDEX IF NOT EXISTS "IX_BusinessAuth_TenantCompanyOperation" ON "BusinessAuthorizations" ("TenantId","CompanyId","OperationCode");
-- RLS must be configured with application tenant context before any production use.
-- DO NOT expose these tables via unrestricted application credentials.
COMMIT;